insert into stats ("key", "name", "max") select "key", "name", "max" from jsonb_populate_recordset(null::stats, $j$[{"key":"strength","name":"Сила","max":10},{"key":"dexterity","name":"Ловкость","max":10},{"key":"intelligence","name":"Интеллект","max":10},{"key":"will","name":"Воля","max":10},{"key":"charisma","name":"Харизма","max":10},{"key":"perception","name":"Восприятие","max":10},{"key":"technique","name":"Техника","max":10},{"key":"luck","name":"Удача","max":10},{"key":"constitution","name":"Телосложение","max":10}]$j$::jsonb);
insert into ranks ("level", "name", "hp_base", "kronos_max") select "level", "name", "hp_base", "kronos_max" from jsonb_populate_recordset(null::ranks, $j$[{"level":1,"name":"Нео","hp_base":20,"kronos_max":60},{"level":2,"name":"Би-ва","hp_base":40,"kronos_max":90},{"level":3,"name":"Тритус","hp_base":60,"kronos_max":150},{"level":4,"name":"Квартикум","hp_base":80,"kronos_max":220},{"level":5,"name":"Пента","hp_base":100,"kronos_max":350},{"level":6,"name":"Гексидиос","hp_base":120,"kronos_max":700},{"level":7,"name":"Гептакул","hp_base":140,"kronos_max":1000},{"level":8,"name":"Октавиос","hp_base":160,"kronos_max":1500},{"level":9,"name":"Нона","hp_base":180,"kronos_max":2000},{"level":10,"name":"Декатуриос","hp_base":200,"kronos_max":2500}]$j$::jsonb);
insert into races ("id", "name", "has_kronos", "implants_allowed", "description") select "id", "name", "has_kronos", "implants_allowed", "description" from jsonb_populate_recordset(null::races, $j$[{"id":"0x001","name":"Новуссит","has_kronos":true,"implants_allowed":true,"description":"Имеет Кронос."},{"id":"0x002","name":"Поляриец","has_kronos":false,"implants_allowed":true,"description":"Не имеет Кронос."},{"id":"0x003","name":"Хуманиец","has_kronos":false,"implants_allowed":false,"description":"Не имеет Кронос и доступа к имплантам. Информационное свойство, жёсткой блокировки нет."}]$j$::jsonb);
insert into classes ("name") select "name" from jsonb_populate_recordset(null::classes, $j$[{"name":"Свой"},{"name":"Рокер"},{"name":"Соло"},{"name":"Гейтбрейкер"},{"name":"Техник"},{"name":"Кочевник"},{"name":"Самурай"},{"name":"Мед-семблер"},{"name":"Трансгрессор"},{"name":"Авангард"},{"name":"Медикус"},{"name":"Нейромант"},{"name":"Зверь"}]$j$::jsonb);
insert into skills ("id", "name", "stat", "tier", "rarity", "description") select "id", "name", "stat", "tier", "rarity", "description" from jsonb_populate_recordset(null::skills, $j$[{"id":"0x001","name":"Плавание","stat":"strength","tier":5,"rarity":"Обычный","description":"Умение плавать. Получите бонус к *этому навыку*, оказавшись в воде, в размере 5n. n - ранг этого навыка. Пассивный."},{"id":"0x002","name":"Владение ближним оружием [Me]","stat":"strength","tier":5,"rarity":"Обычный","description":"Позволяет пользоваться оружием соответствующей категории. Доступная редкость равна уровню навыка.  Пассивный."},{"id":"0x003","name":"Бросок","stat":"strength","tier":5,"rarity":"Обычный","description":"Позволяет поднять и бросить предмет до маленького размера.Сложность броска равняется 15n где n это количество ОП от вас. При провале бросок не попадает в цель.(новое положение определяется гмом)\nБонус навыка 5*уровень навыка."},{"id":"0x004","name":"Атлетика","stat":"strength","tier":6,"rarity":"Необычный","description":"Если вам нужно совершить прыжок или большое усилие, получите бонус 5n к этому навыку. Вы можете вышибать двери и двигать предметы большого размера с бонусом в 5n к этому навыку. n - ранг этого навыка.\n\nРаз в ход вы можете кинуть бросок перед передвижением, если держите в руках оружие. В случае если значение на броске будет больше 70 - вы получите ОП. Для оружия с свойстом Тяжелое бросок происходит с помехой Активный."},{"id":"0x005","name":"Толчок","stat":"strength","tier":6,"rarity":"Необычный","description":"Вы можете совершить 1 АВХ, толкнув цель на прилегающей дистанции. Получите бонус к АТК этого навыка 5n. n - ранг этого навыка. Если атака будет удачной, цель смещается на 1 дистанцию назад. Испытание: Бросок навыка vs ТЕЛО. Активный."},{"id":"0x006","name":"Бой без оружия","stat":"strength","tier":7,"rarity":"Редкий","description":"Если вы сражаетесь в бою без оружия, получите бонус 5n к АТК к следующей вашей атаке. n - ранг этого навыка. Активный."},{"id":"0x007","name":"Владение тяжелым оружием","stat":"strength","tier":7,"rarity":"Редкий","description":"Позволяет пользоваться оружием соответствующей категории. Доступная редкость равна уровню навыка. Пассивный."},{"id":"0x008","name":"Дорога ярости","stat":"strength","tier":7,"rarity":"Редкий","description":"Иногда появляется желание проехаться по канализации с трубой чтобы кому-то вмазать.Вы можете использовать оружия типа [Me] и импланты [A] (за исключением автопушки) для атаки с мотоцикла. Получите бонус +5n к АТК"},{"id":"0x009","name":"Перехват атаки","stat":"strength","tier":7,"rarity":"Редкий","description":"Вы можете совершить блок атаки по вам на дистанции вплотную свободным действием. Количество использований 1-1 3-2 5-3 Активный"},{"id":"0x00a","name":"Защита щитом","stat":"strength","tier":8,"rarity":"Эпический","description":"Главное уметь держать удар. При использовании щита при блокировании, вы можете закрыться на одну атаку больше. Добавьте блок от еще 1 атаки в раунде на 3ем и на 5ом уровнях навыка.Активное"},{"id":"0x00b","name":"Удар в рывке","stat":"strength","tier":8,"rarity":"Эпический","description":"Перемещаясь на расстояние более двух оп от точки начала ранда, вы можете использовать этот навык при совершении атаки в ближнем бою чтобы получить бонус к атк или укл +5n. n - уровень навыка"},{"id":"0x00c","name":"Устрашение","stat":"strength","tier":8,"rarity":"Эпический","description":"Грубая сила - хороший инструмент! Пугайте свою цель, чтобы получить желаемое! Испытание: Этот бросок VS Воля *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x00d","name":"Захват","stat":"strength","tier":9,"rarity":"Легендарный","description":"Совершая атаку в ближнем бою можете провести захват своей цели в если вы не используете оружие. Соревнование броска навыка + 5n против силы\\ловкости цели. При провале цель получает неснимаемый эффект дезориентация и не может самостоятельно перемещаться пока находиться в захвате. Цель может совершать проверку испытания в начале каждого своего хода. Вы не можете использовать этот навык снова пока вы держите цель"},{"id":"0x00e","name":"Щит и меч","stat":"strength","tier":9,"rarity":"Легендарный","description":"Вы можете сражаться как великие войны прошлого. При использовании активной защиты щитом вы можете произвести атаку другим выбранным оружием ближнего боя без свойства тяжелое, или дальним оружием класса [p] . Количество использований в бою согласно уровню навыка 1-1 3-2 5-3. Активный."},{"id":"0x00f","name":"Владение пистолетами","stat":"dexterity","tier":5,"rarity":"Обычный","description":"Позволяет пользоваться оружием соответствующей категории. Доступная редкость равна уровню навыка.  Пассивный."},{"id":"0x010","name":"Владение дробовиками","stat":"dexterity","tier":5,"rarity":"Обычный","description":"Позволяет пользоваться оружием соответствующей категории. Доступная редкость равна уровню навыка.  Пассивный."},{"id":"0x011","name":"Владение штурмовыми винтовками","stat":"dexterity","tier":5,"rarity":"Обычный","description":"Позволяет пользоваться оружием соответствующей категории. Доступная редкость равна уровню навыка.  Пассивный."},{"id":"0x012","name":"Владение снайперскими винтовками","stat":"dexterity","tier":5,"rarity":"Обычный","description":"Позволяет пользоваться оружием соответствующей категории. Доступная редкость равна уровню навыка.  Пассивный."},{"id":"0x013","name":"Владение пистолет-пулеметами","stat":"dexterity","tier":5,"rarity":"Обычный","description":"Позволяет пользоваться оружием соответствующей категории. Доступная редкость равна уровню навыка.  Пассивный."},{"id":"0x014","name":"Механический взлом","stat":"dexterity","tier":6,"rarity":"Необычный","description":"Позволяет взламывать механические, навесные замки. Бонус 5n*к броску навыка*, где n - уровень этого навыка. Активный."},{"id":"0x015","name":"Скрытое ношение","stat":"dexterity","tier":6,"rarity":"Необычный","description":"Вы можете спрятать в одежде оружие класса пистолет. Бонус 5n *к броску навыка*, где n - уровень этого навыка. Пассивный."},{"id":"0x016","name":"Акробатика","stat":"dexterity","tier":6,"rarity":"Необычный","description":"Позволяет вам быстро преодолевать препятствия. При падении с высоты успешный бросок акрабатики снижает получаемый урон в два раза. Сложность броска 12n. n - количество ОП падения. \nБонус навыка 5*уровень навыка"},{"id":"0x017","name":"Скрытность","stat":"dexterity","tier":7,"rarity":"Редкий","description":"Позволяет скрываться вне прямой видимости противников,  со штрафом 25 сливаясь с местностью, а также двигаться как можно тише. Бонус 5n к броску навыка, где n - уровень этого навыка. Активный."},{"id":"0x018","name":"Огонь на подавление","stat":"dexterity","tier":7,"rarity":"Редкий","description":"Применив этот навык перед атакой автоматическим оружием, вы попытаетесь наложить на вашу цель эффект Подавлен. Цель должна пройти испытание воли против (бросок этого навыка минус 25), чтобы избежать эффекта. Атака не наносит урона и иных эффектов, но получает взрывчатое 1 на первом ранге, 2 на третьем, 3 на пятом и накладывает эффект Подавлен на все цели в зоне попадания. Бонус 5n к броску навыка, где n - уровень навыка. Активный."},{"id":"0x019","name":"Уход из под удара","stat":"dexterity","tier":7,"rarity":"Редкий","description":"Вы можете совершить уклонение атаки по вам на дистанции вплотную свободным действием. Количество использований 1-1 3-2 5-3 Активный"},{"id":"0x01a","name":"Шальная пуля","stat":"dexterity","tier":7,"rarity":"Редкий","description":"Ваши знания геометрии выше среднего. Пройдя сложность 70 при броске этого навыка вы получаете возможность отправить один из своих авх в дополнительную цель. Или же совершить необычный трюк с огнестрельным оружием при разрешении гма. Бонус к броску 5n. n - уровень навыка"},{"id":"0x01b","name":"Знаток быстрых ударов","stat":"dexterity","tier":7,"rarity":"Редкий","description":"В бою без оружия вы получаете доп авх на 3ем и 5ом уровне навыка. Пассивный"},{"id":"0x01c","name":"Стрельба из машины","stat":"dexterity","tier":8,"rarity":"Эпический","description":"Уменьшает штраф к ТЧН на стрельбу из машины на 5n, где n - уровень этого навыка.На пятом уровне навыка позволяет стрелять из любого огнестрела с места водителя. (Искл. тяжелое)"},{"id":"0x01d","name":"Быстрое укрытие","stat":"dexterity","tier":8,"rarity":"Эпический","description":"Занятие укрытия, не занимает од при прохождении проверки 100-5n этого навыка. Где n -  уровень этого навыка"},{"id":"0x01e","name":"Внезапный скороход","stat":"dexterity","tier":8,"rarity":"Эпический","description":"Вы получаете одно ОП. 3 КД. Число использований в бою/Уровень навыка: 1-1 2-3 3-5. На 2 и 4 уровнях навыка КД сокращается на 1. Активный."},{"id":"0x01f","name":"Внимательность","stat":"perception","tier":5,"rarity":"Обычный","description":"Когда вы изучаете предмет, вы можете заметить мелкие детали. Получите бонус 5n к этому броску, где n - уровень этого навыка. Пассивный."},{"id":"0x020","name":"Обострение чувств","stat":"perception","tier":5,"rarity":"Обычный","description":"В ситуациях когда вы концетнрируетесь на звуке вы можете разобрать его лучше других.. Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный."},{"id":"0x021","name":"Рыбная ловля","stat":"perception","tier":6,"rarity":"Необычный","description":"Вы знаете, когда вытащить удочку!  *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x022","name":"Поиск ловушек","stat":"perception","tier":6,"rarity":"Необычный","description":"Исследуя опасную местность, вы можете обнаружить ловушки поблизости.  *Получите бонус к данному броску 5n, где n - уровень навыка. Вы также можете добавить бонусы от оптики и других предметов. Пассивный.*"},{"id":"0x023","name":"Прикладное искусство","stat":"perception","tier":6,"rarity":"Необычный","description":"Вас тянет к созданию прекрасного, каким бы оно ни было в ваших глазах. Вы получаете бонус +5n при создании картин или скульптур, где n - ваш уровень навыка. Также эффект позволяет вам разбираться в этих видах искусства."},{"id":"0x024","name":"Чуйка ценностей","stat":"perception","tier":7,"rarity":"Редкий","description":"В поиске ценностей, вне боя, бросьте этот навык. Получите бонус 5n к этому броску, где n - уровень этого навыка. Пассивный."},{"id":"0x025","name":"Слежка","stat":"perception","tier":7,"rarity":"Редкий","description":"Не теряйте цель из виду. В ходе слежки, примените этот навык. В ответ, цель бросает ЛОВК. Испытание. *Получите бонус к данному броску 5n, где n - уровень навыка. Вы также можете добавить бонусы от оптики и других предметов. Пассивный.*"},{"id":"0x026","name":"Охотник","stat":"perception","tier":7,"rarity":"Редкий","description":"Вы легко можете определить местоположение диких зверей и к-существ на локации. Получите бонус к данному броску 5n, где n - уровень навыка. Вы также можете добавить бонусы от оптики и других предметов. Пассивный."},{"id":"0x027","name":"Психологический портрет","stat":"perception","tier":8,"rarity":"Эпический","description":"При броске выше 110, вы можете составить при первой встрече краткий психологический портрет увиденной личности. *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x028","name":"Чувство опасности","stat":"perception","tier":9,"rarity":"Легендарный","description":"Вы чувствуете скрытую враждебность цели. В ответ цель бросает ХАР. Испытание. *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x029","name":"Обнаружение врагов","stat":"perception","tier":9,"rarity":"Легендарный","description":"До начала боя, бросьте этот навык. Вы узнаете точное местоположение, умения и вооружение противников. Требуется наличие оптики или нужного базиса. Сложность проверки определяет ГМ. *Получите бонус к данному броску 5n, где n - уровень навыка. Вы также можете добавить бонусы от оптики и других предметов Пассивный.*"},{"id":"0x02a","name":"Шестое чувство","stat":"perception","tier":9,"rarity":"Легендарный","description":"Ваше интуиция и восприятие позволяют предсказывать последующие события. *Получите бонус к броску ИНИЦИАТИВЫ 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x02b","name":"Охотник на убийц","stat":"perception","tier":9,"rarity":"Легендарный","description":"Ваши глаза могут обнаружить противника с технологиями стелс. *Получите бонус к данному броску 5n, где n - уровень навыка. Вы также можете добавить бонусы от оптики и других предметов. Активный.*"},{"id":"0x02c","name":"Владение Умным оружием","stat":"technique","tier":5,"rarity":"Обычный","description":"Позволяет пользоваться оружием с эффектом Умное. Доступная редкость равна уровню навыка.  Пассивный."},{"id":"0x02d","name":"Вождение (гражданский транспорт)","stat":"technique","tier":5,"rarity":"Обычный","description":"Позволяет водить наземный легковой и грузовой гражданский транспорт. *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x02e","name":"Знание электроники","stat":"technique","tier":5,"rarity":"Обычный","description":"Вы неплохо разбираетесь в электрике. Можно определить причину неполадки в электросхемах. *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x02f","name":"Владение технологическим оружием","stat":"technique","tier":6,"rarity":"Необычный","description":"Позволяет пользоваться оружием с эффектом Технологичное. Доступная редкость равна уровню навыка.  Пассивный."},{"id":"0x030","name":"Использование силовых костюмов","stat":"technique","tier":6,"rarity":"Необычный","description":"Позволяет вам управляться со сложной электроникой силовой брони. Редкость предмета должна быть  равна уровню навыка. Пассивный."},{"id":"0x031","name":"Ремонт электроники и техники","stat":"technique","tier":6,"rarity":"Необычный","description":"Вы можете починить сложноустроенную электротехнику. Включая робототехнику и андроидов. *Получите бонус к данному броску 5n, где n - уровень навыка. Активный.*"},{"id":"0x032","name":"Знание имплантов","stat":"technique","tier":6,"rarity":"Необычный","description":"Вы можете узнать установленные импланты видимой цели пройдя испытание в зависимости от редкости импланта. Пассивный\n\n30 - Обычный\n\n50 - Необычный\n\n70 - Редкий\n\n90 - Эпически\n\n110 - Легендарный\n\n**Не позволяет узнать о \"Капсула Крыса\" \"Скрытая кобура  \"**"},{"id":"0x033","name":"Криминалистика","stat":"technique","tier":7,"rarity":"Редкий","description":"Умение более углубленного анализа места преступления. Пример: Понять калибр оружия или траекторию по отверстию в стене. *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x034","name":"Капитан","stat":"technique","tier":7,"rarity":"Редкий","description":"Умение управлять морскими судами . *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x035","name":"Архитектор","stat":"technique","tier":7,"rarity":"Редкий","description":"Позволяет предполагать где могут находиться те или иные комнаты или интересующие вас критические важные элементы здания, исходя из логики строительства.Получите бонус 5n к броску, где n уровень навыка.*"},{"id":"0x036","name":"Пилотирование","stat":"technique","tier":7,"rarity":"Редкий","description":"Умение водить аэромобили. *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x037","name":"Знание взрывчатки","stat":"technique","tier":7,"rarity":"Редкий","description":"Вы можете как подготовить взрывчатку правильно, так и обезвредить ее. *Получите бонус к данному броску 5n, где n - уровень навыка. Активный.*"},{"id":"0x038","name":"Установка улучшений","stat":"technique","tier":7,"rarity":"Редкий","description":"Навык позволяет устанавливать импланты, будучи мед-семблером или модули для меха будучи техником (для мехов).  *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x039","name":"Управление мехами","stat":"technique","tier":7,"rarity":"Редкий","description":"Вы можете управлять мехами при наличии необходимого оборудования. Уровень навыка определяет редкость меха, доступного к управлению, а также максильного возможную дальность контроля. 0 - вплотную. 1 - ближняя. 2 - средняя. 3 - дальняя. 4 - сверхдальняя. 5 - любая дистанция в пределах одной локации. Пассивный."},{"id":"0x03a","name":"Первая помощь","stat":"technique","tier":8,"rarity":"Эпический","description":"Позволяет вам пользоваться набором первой помощи в боевых условиях для стабилизации опасных для жизни эффектов. Позволяет снять кровотечение с полной тратой хода и успешной проверкой этого навыка Со сложностью (количество кровотечения x 2). Бонус к броску навыка +5n - где n уровень навыка."},{"id":"0x03b","name":"Хирургия","stat":"technique","tier":8,"rarity":"Эпический","description":"Позволяет проводить хирургические операции для лечения. Требуется: Мед-сембер/Медикус. *Получите бонус к данному броску 5n, где n - уровень навыка. Активный.*"},{"id":"0x03c","name":"Проведение пластических операций","stat":"technique","tier":8,"rarity":"Эпический","description":"В *своей клинике* вы можете провести сеанс по смене внешности человека. Требуется Мед. Семблер. Результат вашего броска навыка со штрафом 20 будет являться сложностью для опознания личности. *Получите бонус к данному броску 5n, где n - уровень навыка. Смена внешности таким образом возможно раз в игровой день. Активный.*"},{"id":"0x03d","name":"Поиск уязвимостей","stat":"technique","tier":8,"rarity":"Эпический","description":"Вы можете легко обнаруживать уязвимости в броне противника. Используйте этот навык, в том числе, вместо броска ВОСПР на обнаружение слабостей  рукотворных механизмов. При прохождении заданной ГМом сложности, вы узнаете все уязвимости цели. *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x03e","name":"Оверклокинг","stat":"technique","tier":9,"rarity":"Легендарный","description":"Часть урона от следующего АВХ технологического оружия проникает через деф п  цели и доп хп. Количество урона которое пройдет равно 10n n - уровень навыка \nАктивный."},{"id":"0x03f","name":"Ломка оружия","stat":"technique","tier":9,"rarity":"Легендарный","description":"Вы заряжаете свое технологичное оружие нацеливая его на вооруженного противника, следующая ваша атака обладает одним авх. Цель должна пройти испытание техники 5n+d100 для того чтобы его починить в начале каждого своего хода. После чему ему требуется остыть в течении 6 - n ходов, где n - уровень навыка.Пока оружие остывает невозможно использовать с ним другие тех навыки. Активный."},{"id":"0x040","name":"Высокотехнологичный ремонт","stat":"technique","tier":9,"rarity":"Легендарный","description":"Вы способны ремонтировать военную технику, летательные аппараты, суперкомпьютеры, наноэлектронику и любые другие сверхтехнологии.В том числе меха техника, чья редкость равна уровню навыка *Получите бонус к данному броску 5n, где n - уровень навыка. Активный.*"},{"id":"0x041","name":"Готовка","stat":"intelligence","tier":5,"rarity":"Обычный","description":"Вы можете приготовить вкусное блюдо.  *Получите бонус к данному броску 5n, где n - уровень навыка. Активный.*"},{"id":"0x042","name":"Понимание животных","stat":"intelligence","tier":5,"rarity":"Обычный","description":"Вы понимаете паттерны поведения обычных животных.  *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x043","name":"Использование терминалов","stat":"intelligence","tier":5,"rarity":"Обычный","description":"Вы можете использовать сложные компьютеры с профессиональным софтом.  *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x044","name":"Поиск информации в омнинете","stat":"intelligence","tier":5,"rarity":"Обычный","description":"Вы отлично находите информацию среди множества ссылок и статей.  *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x045","name":"Оценка","stat":"intelligence","tier":6,"rarity":"Необычный","description":"Большинство вещей, имеют свою цену в омнинете, но бывают случаи когда вы натыкаетесь на что-то непонятное и ваш взгляд быстро помогает понять истинную ценность предмета.  Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный."},{"id":"0x046","name":"Картография","stat":"intelligence","tier":6,"rarity":"Необычный","description":"Вы отлично разбираетесь в картах. Легко ориентируетесь по ним на местности.  *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x047","name":"Общая эрудиция","stat":"intelligence","tier":6,"rarity":"Необычный","description":"Вы знаете много фактов о мире Гаянокса, включая знания химии, физики, биологии и истории. *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x048","name":"Дипломатия","stat":"intelligence","tier":6,"rarity":"Необычный","description":"В отличие от других умений, также предназначенных  оказывать влияние, Дипломатия никогда не приведет результату худшему чем был до броска.\nУспешная проверка позволит вам предсказать возможный исход определенного способа ведения переговоров и выбрать наилучший подход. Но само успешное применение этого навыка не обозначает успех переговоров *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x049","name":"Обнаружение гейтбрейкера","stat":"intelligence","tier":7,"rarity":"Редкий","description":"Вы можете определить что вас взламывают и вместе с этим местоположение гейтбрейкера, который пытается вас взломать. Испытание: Этот навык VS \"первичный взлом\". *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x04a","name":"Биохимия и медицина","stat":"intelligence","tier":7,"rarity":"Редкий","description":"Вы отлично разбираетесь в биологических и химических аспектах и формулах. Знаете устройство живых существ и как вещества влияют на них наизусть.  *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x04b","name":"Взлом электронных замков","stat":"intelligence","tier":7,"rarity":"Редкий","description":"Вы можете взламывать электронные и магнитные замки через локальную сеть или консоль. *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x04c","name":"Знание языков","stat":"intelligence","tier":7,"rarity":"Редкий","description":"Вы настоящий полиглот. Без использование автопереводчика нейросети, вы понимаете что вам говорит иностранец.  *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x04d","name":"Первичный взлом","stat":"intelligence","tier":7,"rarity":"Редкий","description":"**Основной навык гейтбрейкеров.** Позволяет взламывать слои \"Льда\" локальных сетей с защитой и сенсориумов противников. Снижает сложность взлома на значение броска данного навыка. Требуется класс: гейтбрейкер. *Получите бонус к данному броску 5n, где n - уровень навыка. Активный.*"},{"id":"0x04e","name":"Милосердность","stat":"intelligence","tier":7,"rarity":"Редкий","description":"Надо ценить жизнь, даже жизнь врагов!  Вы можете заявить свою атаку как нелетальную. Использовав этот навык вы должны пройти проверку в 80 при каждой атаке. Умное оружие добавляет бонус к броску  4*на редкость используемого оружия.Получите бонус к данному броску 5n, где n - уровень навыка.\nПассивное"},{"id":"0x04f","name":"Знание рун","stat":"intelligence","tier":8,"rarity":"Эпический","description":"Вы понимете письменность древнего языка иниев. *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x050","name":"Криптография","stat":"intelligence","tier":8,"rarity":"Эпический","description":"Позволяет расшифрововать сложные шифры, проверка навыка на 80+ дает название шифра и ключ, на 120+ выполучаете расшифрованный текст. *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x051","name":"Концептуализация","stat":"intelligence","tier":8,"rarity":"Эпический","description":"Позволяет персонажу составлять картину произошедшего в своем сознании, сопоставляя различные обстоятельства чтобы получить визуальный результат. *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x052","name":"Биоинжинерия","stat":"intelligence","tier":9,"rarity":"Легендарный","description":"Вы стоите на передовой генной биоинженерии. Анализ мутаций существ позволяет выявлять их сильные и слабые места. Также вы хорошо разбираетесь в современных недугах. *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x053","name":"Мастер тактик","stat":"intelligence","tier":9,"rarity":"Легендарный","description":"Находясь в опасной ситуации вы можете проанализировать окружение определяя наиболее оптимальные пути для передвижения в случае боя. Ваши n союзников получают в первом раунде боя бонусные очки ОП (1:1; 3;2; 5;3) в зависимости от уровня навыка. n равно уровню навыка. Мастер тактик может быть применен на каждого союзника только один раз. Пассивный"},{"id":"0x054","name":"Знание кронологии","stat":"intelligence","tier":9,"rarity":"Легендарный","description":"Вы неплохо разбираетесь в тонкостях манипуляций с к-энергией, а также с процессами в этой сфере. Используйте при анализе событий, связанных с к-энергией. *Получите бонус к данному броску 5n, где n - уровень навыка. Активный.*"},{"id":"0x055","name":"Эксперт эфир-модулятор","stat":"intelligence","tier":9,"rarity":"Легендарный","description":"По внешнему виду человека перед вами, вы можете определить является ли он эфир-модулятором, а также его специализацию. Испытание: Бросок навыка VS УДЧ. *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x056","name":"Высокоточный анализ истины","stat":"intelligence","tier":9,"rarity":"Легендарный","description":"Вы без труда определяете когда ваш собеседник вам врет. Получите бонус к данному броску 5n, где n - уровень навыка когда проверяете человека на вранье. Пассивный."},{"id":"0x057","name":"Убеждение","stat":"charisma","tier":5,"rarity":"Обычный","description":"Некоторым людям нужен дополнительный толчок, чтобы сделать то, что вы от них хотите. Достататочно несколько нужных слов. *Получите бонус к данному броску 5n, где n - уровень навыка. Действует прибавка от роскоши. Пассивный.*"},{"id":"0x058","name":"Очарование","stat":"charisma","tier":6,"rarity":"Необычный","description":"Вы вызываете симпатию у изначально невраждебных людей. *Получите бонус к данному броску 5n, где n - уровень навыка. Действует прибавка от роскоши. Пассивный.*"},{"id":"0x059","name":"Допрос","stat":"charisma","tier":6,"rarity":"Необычный","description":"Вы умеете развязывать языки без насильственных средств. Испытание: Этот бросок VS Воля. *Получите бонус к данному броску 5n, где n - уровень навыка. Действует прибавка от роскоши. Пассивный.*"},{"id":"0x05a","name":"Музыкальное искусство","stat":"charisma","tier":6,"rarity":"Необычный","description":"Медведь не наступал, Поражайте всех замечательной игрой на инструментах или с помощью своего голоса *Получите бонус к данному броску 5n, где n - уровень навыка. Действует прибавка от роскоши. Пассивный.*"},{"id":"0x05b","name":"Этикет","stat":"charisma","tier":7,"rarity":"Редкий","description":"Вы высших кругах и среди интеллигенции, вы чувствуете себя как рыба в воде. Производите впечатление своей элегантностью! *Получите бонус к данному броску 5n, где n - уровень навыка. Действует прибавка от роскоши. Пассивный.*"},{"id":"0x05c","name":"Соблазн","stat":"charisma","tier":7,"rarity":"Редкий","description":"Вы вызываете влечение к вам у любых разумных существ. Испытание: Этот бросок VS Воля/Интеллект. *Получите бонус к данному броску 5n, где n - уровень навыка. Действует прибавка от роскоши. Пассивный.*"},{"id":"0x05d","name":"Артистизм","stat":"charisma","tier":7,"rarity":"Редкий","description":"Вы — истинный творец перфоманса. Ваше тело и голос сливаются в единой гармонии, позволяя вам виртуозно владеть искусством танца, стихосложения и эффектного позирования. Вы завораживаете публику каждым своим движением и словом. Получите бонус к данному броску 5n, где n - уровень навыка. Действует прибавка от роскоши. Пассивный."},{"id":"0x05e","name":"Запугивание","stat":"charisma","tier":8,"rarity":"Эпический","description":"Тихая угроза страшнее кулака! Пугайте свою цель, чтобы получить желаемое! Испытание: Этот бросок VS Воля *Получите бонус к данному броску 5n, где n - уровень навыка. Действует прибавка от роскоши. Пассивный.*"},{"id":"0x05f","name":"Язык телодвижений","stat":"charisma","tier":8,"rarity":"Эпический","description":"Вы можете догадаться о реальных намерениях цели, хорошо понимаете их эмоции, проанализировав ее поведение и мимику. Испытание: Этот бросок VS ТЕЛО *Получите бонус к данному броску 5n, где n - уровень навыка. Пассивный.*"},{"id":"0x060","name":"Маскировка","stat":"charisma","tier":8,"rarity":"Эпический","description":"Вы можете раствориться в толпе, или выдать себя за другого. В случае попытки раскрытия или обнаружения происходит противостояние этого навыка и ВОСП. Получите бонус к данному броску 5n, где n - уровень навыка. Обнаружение можно использовать не чаще 6 игровых часов."},{"id":"0x061","name":"Мастер лжи и обмана","stat":"charisma","tier":9,"rarity":"Легендарный","description":"Вы можете легко обмануть человека. В ваши слова верят как в священные догмы, если вы не несете полную чушь. Испытание: Этот бросок VS Восприятие(распознание лжи)/Интеллект/Воля. *Получите бонус к данному броску 5n, где n - уровень навыка. Действует прибавка от роскоши. Пассивный.*"},{"id":"0x062","name":"Боевой гимн","stat":"charisma","tier":9,"rarity":"Легендарный","description":"Ваша металлическая рука извлекает правильные ноты для разжигания толпы.**Эффект** от музыкального инструмента получает бафф в 5 * n (Где n - уровень навыка). Активный. Треб Рокер"}]$j$::jsonb);
insert into abilities ("id", "name", "kind", "class_requirement", "description") select "id", "name", "kind", "class_requirement", "description" from jsonb_populate_recordset(null::abilities, $j$[{"id":"0x001","name":"Ловкие пальчики","kind":"ability","class_requirement":null,"description":"Вы получаете дополнительное действие атаки. Раз в бой."},{"id":"0x002","name":"Я Особенный","kind":"ability","class_requirement":null,"description":"Вы получаете +1 ИЧ. Если вы зверь вы получаете + один Л слот способностей зверя\nПассивное."},{"id":"0x003","name":"Наш пострел везде поспел","kind":"ability","class_requirement":null,"description":"Вы можете использовать 2 способности за раз. Пассивное."},{"id":"0x004","name":"Мастер","kind":"ability","class_requirement":null,"description":"Вы можете использовать два активных навыка в одном раунде. Пассивное."},{"id":"0x005","name":"Перемена блюд","kind":"ability","class_requirement":null,"description":"Вы можете сменить оружие без траты ОД. КД 1"},{"id":"0x006","name":"Атака вдогонку","kind":"ability","class_requirement":null,"description":"Если противник передвигается в пределах атаки вашим ближним оружием вы можете нанести ему одну атаку вне инициативы. Пассивное"},{"id":"0x007","name":"Преимущество высоты","kind":"ability","class_requirement":null,"description":"Все кончено! у меня есть преимущество высоты. Если вы находитесь выше своей цели то вы получаете бонус 5n к атакам оружием или метакризной по целям ниже вас, где n = рангу персонажа. Пассивный"},{"id":"0x008","name":"Связи в тенях","kind":"ability","class_requirement":null,"description":"Только при создании персонажа. Вы знаете когда и где искать Черный рынок, но даже так вы должны соблюдать осторожность как и все остальные солюдая его правила."},{"id":"0x009","name":"Мастерство прицеливания","kind":"ability","class_requirement":null,"description":"Вы можете потратить свое од вместе с использованием этой способности чтобы получить бонус +20 ТЧН на следующую атаку, не позднее следующего вашего хода"},{"id":"0x00a","name":"Магма в венах","kind":"ability","class_requirement":null,"description":"Вы можете использовать второй активный имплант в бою. КД 1"},{"id":"0x00b","name":"Неутомимость","kind":"ability","class_requirement":null,"description":"Вы игнорируете первые 3 уровня усталости"},{"id":"0x00c","name":"Игра с позициями","kind":"ability","class_requirement":null,"description":"Вы можете в начале боя поменяться своей инициативой с тем кто находиться ниже вас по согласию принимающего"},{"id":"0x00d","name":"Пламенный сердцем","kind":"ability","class_requirement":null,"description":"При броске тела на перегрев вы имеете преимущество. Пассивная"},{"id":"0x00e","name":"Путь познания","kind":"ability","class_requirement":"Самурай","description":"В начале раунда вы бросаете бросок nd10 (где n - количество сосредоточений). Значение броска будет прибавкой к вашему АТК ближним оружием. Пассивная.\nВ начале каждого хода вы получаете 1 сосредоточение.\nпозволяет пользоваться Всеми имплантами с пометкой \"Треб. Самурай пути познания\"\nНе позволяет иметь другую способность пути\n\"Спокойствие, концентрация, познание...\""},{"id":"0x00f","name":"Путь жертвы","kind":"ability","class_requirement":"Самурай","description":"В конце каждого хода вы восстанавливаете 4n здоровья, где n-номер ранга\nПозволяет пользоваться Всеми имплантами с пометкой \"Треб. Самурай пути жертвы\"\nНе позволяет иметь другую способность пути.\n\"Служение, честь, жертва.\""},{"id":"0x010","name":"Путь риска","kind":"ability","class_requirement":"Самурай","description":"Формула Перегрева меняется с 10+20n на 15n , Где n-количество Перегрева на вас.\nоцепенение меняется на дезориентацию\nпозволяет пользоваться Всеми имплантами с пометкой \"Треб. Самурай пути риска\"\nНе позволяет иметь другую способность пути.\n\"Пламя, сила, риск!\""},{"id":"0x011","name":"Путь безумия","kind":"ability","class_requirement":"Самурай","description":"Вы можете самостоятельно увеличить степень безумия на 1(0->1->2->3->4). В конце боя вы проходите испытание воли 50, при провале она остается такой навсегда. При броске 100 на изначальном кубике вы излечиваетесь полностью от кронодегродации. \nКронодегродаия для вас изменена на Безумие.\nПри получении пути вы получаете в способности сразу все стадии безумия, после чего прописываете какая у вас в окне состояния.  \nпозволяет пользоваться Всеми имплантами с пометкой \"Треб. Самурай пути безумия\"\nНе позволяет иметь другую способность пути.\n\"Бесстрашие, вера, безумие?\""},{"id":"0x012","name":"Последнее безумие?","kind":"ability","class_requirement":"Самурай","description":"Вы получаете доступ к 4 степени Безумия. Теперь после смерти в 3 вы не умираете. Ваш интеллект становится равен одному. Все боевые броски имеют преимущество, и в течении 2 ходов вас невозможно убить. Через 2 хода вы проходите испытание d100. \n0-40 вы умерли\n41-80 Вы вернулись на 3 стадию и падаешь без сознания с 1 ХП теряете d3 интеллекта (не меньше 1)\n81-95 Вы вернулись на 3 стадию и падаешь без сознания с 1 ХП\n96-100 - Этот имплант исчезает из тела. Ваша степень Безумия откатывается до 2. \nТреб. Самурай пути безумия"},{"id":"0x013","name":"Первая стадия Безумия","kind":"ability","class_requirement":"Самурай","description":"Выдается вместо кронодегродации если имеется способность На пути к безумию\n**+4n АТК ближним оружием -4n АТК дальним оружием\nГде n Ранг персонажа**\nВозможность использовать раз в бой два активных импланта в ход"},{"id":"0x014","name":"Вторая стадия Безумия","kind":"ability","class_requirement":"Самурай","description":"Выдается вместо кронодегродации если имеется способность На пути к безумию\n**+6n АТК ближним оружием -6n АТК дальним оружием + 15 деф А -90 макс хп\nГде n Ранг персонажа**\nИспользование Двух активных имплантов в ход два раза в Бой\nИспользование  импланта имеет шанс провалиться, бросок д100 при значении <30 карта или имплант считаются использованными, но не дают положительного эффект. При броске >70 на вас не накладывается перегрев."},{"id":"0x015","name":"Третья стадия Безумия","kind":"ability","class_requirement":"Самурай","description":"Выдается вместо кронодегродации если имеется способность На пути к безумию\n**+10n АТК ближним оружием -10n АТК дальним оружием, -60 деф п, + 60 деф а, - 140 макс хп, СОПР \nГде n Ранг персонажа**\nВсе ваши активные импланты имеют на 1КД меньше \nИспользование импланта имеет шанс провалиться, бросок д100 при значении <40 карта или имплант считаются использованными, но не дают положительного эффекта, При броске >80 вы получаете все положительные эффекты импланта, но он не считается использованным (не уходит в кд, и не дает перегрев) \nПадение в предсмертное состояние на третей стадии вызывает активную реакцию разрывая тело носителя болезни на части вызывая мгновенную смерть и создавая зону с опасным содержанием кроноса в радиусе 3ех оп. \nСпас бросок телосложение 80, при провале пораженные цели получают стадию кронодеградации. При наличии стадии она переходит на след этап"},{"id":"0x016","name":"Скоротечность весны","kind":"ability","class_requirement":"Самурай","description":"Если ваш класс - Самурай, то ваша следующая атака ближнем оружием накладывает дополнительные 30 кровотечения"},{"id":"0x017","name":"Где твоя мотивация","kind":"ability","class_requirement":"Самурай","description":"В начале раунда вы можете использовать эту способность вместо обычной защиты. Вы совершаете бросок атаки ближним оружием против ВСЕХ атак одного противника. Атаки противника уменьшаются на значение максимального АТК вашей атаки. Если таким образом удалось заблокировать ВСЕ АВХ противника - это действие считается быстрым. Если противник атаковал вас дальним оружием , ему возвращаются все АВХ сниженные до 0, их урон равен изначальному урону противника. Вы получаете бонус 3n к этому броску атаки, где n - это ваш ранг"},{"id":"0x018","name":"Еще не пал","kind":"ability","class_requirement":"Самурай","description":"Когда ваше здоровье опускается до 0 вы можете пройти испытание телослоения со сложностью 75. При успехе ваше хп становиться 1, а счетчик бросков на смерть получает +1 провал. Повторное использование способности возможно пока выши провалы не достигли 3ех. Пассивная"},{"id":"0x019","name":"Долг еще не оплачен","kind":"ability","class_requirement":"Самурай","description":"Вы научились игнорировать предупреждения от имплантов и использовать их чаще. Когда ваш имплант находиться в кд вы можете вновь его задействовать взамен получая чистый урон в количестве 100 если имплант ОС то 150"},{"id":"0x01a","name":"Зажигаем!","kind":"ability","class_requirement":"Рокер","description":"Если ваш класс - Рокер, выберите персонажа. Первый его следующий бросок получит d30 от вашего броска. Если бросок боевой, то бонус идет к базовому АТК. \nЧисло использований за 1 ИРЛ день: 1-4 ранг - 1, 5 - 2, 7 - 3, 9 - 4."},{"id":"0x01b","name":"Ударное соло!","kind":"ability","class_requirement":"Рокер","description":"Если ваш класс - Рокер, выберите любой боевой бросок, дает возможность совершить его вновь. Раз в бой."},{"id":"0x01c","name":"Мэшап","kind":"ability","class_requirement":"Рокер","description":"Если ваш класс - Рокер. Вы можете использовать два мотива за один ОД, Использоваться будет один бросок харизмы для обоих"},{"id":"0x01d","name":"На бис!","kind":"ability","class_requirement":"Рокер","description":"Треб. класс Рокер. Один раз за бой вы можете исполнить свой главный хит. Выберите одного союзника. Тем самым вы обнуляете КД способностей одной цели."},{"id":"0x01e","name":"Адреналиновый бит","kind":"ability","class_requirement":"Рокер","description":"Треб. класс Рокер. Ваше выступление заставляет адреналин кипеть. Вы можете дать дополнительное ОД одной выбранной цели."},{"id":"0x01f","name":"Особый маневр","kind":"ability","class_requirement":"Соло","description":"Если ваш класс - Соло, вы получаете дополнительный ОД и ОП. Раз в бой."},{"id":"0x020","name":"Сквозной калибр","kind":"ability","class_requirement":"Соло","description":"Треб. Соло. Ваши атаки из снайперских винтовок обладают пробивной силой. Если ваш выстрел убивает противника или цель уворачивается, пуля летит дальше. Любой персонаж, находящийся на линии огня прямо за изначальной целью, получает атаку с теми же результатами броска ТЧН. Пассивная"},{"id":"0x021","name":"Удар из тени","kind":"ability","class_requirement":"Соло","description":"Треб. Соло Если вы атакуете цель, находясь в стелсе, ваша первая атака получает бонус +25к КШ. Пассивная"},{"id":"0x022","name":"Геометрия смерти","kind":"ability","class_requirement":"Соло","description":"Треб. Соло Потратив 1 ОД, вы рассчитываете сложную траекторию для одного выстрела. Эта атака полностью игнорирует бонусы, которые противник получает от укрытия"},{"id":"0x023","name":"Импульс стрелка","kind":"ability","class_requirement":"Соло","description":"Треб. Соло Если вы убиваете врага или выводите его из строя из пистолета или ПП, вы мгновенно получаете 2 бесплатных ОП на следующий раунд"},{"id":"0x024","name":"Встречный свинец","kind":"ability","class_requirement":"Соло","description":"Треб. Соло Если противник в свой ход входит в  зону оптимального поражения вашего экипированного оружия и остается в ней на момент начала вашего хода вы можете провести одну атаку быстрым действием."},{"id":"0x025","name":"Шквальный сектор","kind":"ability","class_requirement":"Соло","description":"Треб. Соло Если в течение одного раунда вы совершаете атаки по 3 и более разным целям из автоматического оружия, все цели, по которым вы успешно попали, автоматически получают эффект «Подавлен». Пассивная способность"},{"id":"0x026","name":"Метка наемника","kind":"ability","class_requirement":"Соло","description":"Треб. Соло вы накладываете на цель метку. Раз в раунд если вы ее атакуете вы получаете бонус 10 АТК на все последующие атаки в раунде, бонус накопительный. Вы можете наложить только одну метку, смена цели возможна только при устранении изначальной цели, бонус при этом сбрасывается"},{"id":"0x027","name":"Не тот человек в том месте","kind":"ability","class_requirement":"Соло","description":"Треб. Соло. Оказываясь под огнем вы можете использовать ближайшего персонажа как укрытие пройдя противостояниие навыка \"Уход из под удара\" против \"Атлетики\" цели. При успехе атаки оказываются направленны в выбранную цель с получением урона на старт ее хода"},{"id":"0x028","name":"Использование окружения","kind":"ability","class_requirement":"Соло","description":"В бою вы можете приметить то что может помочь вам в вашей ситуации, совершив атаку вы можете сделать бросок внимательности 90+ при успехе вы можете провести свободную атаку с использованием бонуса 8n атк на расстоянии до 3ех оп от вас. Не более двух раз за бой"},{"id":"0x029","name":"Рободруг","kind":"ability","class_requirement":"Техник","description":"Если ваш класс - Техник, вы можете добавить 5n к любой проверке вашего меха ( n - порядковый номер ранга персонажа)."},{"id":"0x02a","name":"Заслон","kind":"ability","class_requirement":"Техник","description":"Мех (призма) принимает весь урон на себя за место хозяина"},{"id":"0x02b","name":"Реальная сталь","kind":"ability","class_requirement":"Техник","description":"игрок может отдать свои од и оп меху (призме), взяв ручное управление"},{"id":"0x02c","name":"Стальная месть","kind":"ability","class_requirement":"Техник","description":"Мех после уничтожения может произвести атаку в течении ещё 1 хода после смерти. имеет помеху на атаку, а так же не может двигаться , и использховать активные модули"},{"id":"0x02d","name":"Мастер управления","kind":"ability","class_requirement":"Техник","description":"Вы можете использовать ваши навыки и способности боя при атаке или защиты с помощью меха. Пассивный"},{"id":"0x02e","name":"Повелитель стихии","kind":"ability","class_requirement":"Трансгрессор","description":"Если ваш класс - Трансгрессор, +5n АТК при использовании общих базисов и базисов трансгрессора. ( n - порядковый номер ранга персонажа)."},{"id":"0x02f","name":"Элементальный пробой","kind":"ability","class_requirement":"Трансгрессор","description":"Если вы используете два базиса разных элементальных сущностей в одном кроноимпульсе, итоговая атака игнорирует 20 ДЕФ(п) цели. Пассивное."},{"id":"0x030","name":"Мастер одной стихии","kind":"ability","class_requirement":"Трансгрессор","description":"В бою при использовании уникальных карт одной и той же элементальной сущности вы получаете накопительный бонус к АТК метакризны +8. При использовании карты другой сущности бонус обнуляется"},{"id":"0x031","name":"Эфирный резонанс","kind":"ability","class_requirement":"Трансгрессор","description":"При нанесении критического урона или выведении противника из строя с помощью базиса, вы восстанавливаете 20 единиц Кроноса. Пассивное."},{"id":"0x032","name":"Адаптация метакризны","kind":"ability","class_requirement":"Трансгрессор","description":"При использовании способности следующая ваша карта будет учитываться как карта другой сущности заменяя свой урон на выбранный"},{"id":"0x033","name":"Мне не важно какого размера комната","kind":"ability","class_requirement":"Трансгрессор","description":"Если в вашей карте присутствует атака по площади вы можете добавить к этому параметру величины +1"},{"id":"0x034","name":"Вам лучше пригнуться","kind":"ability","class_requirement":"Трансгрессор","description":"Перед использованием карты вы можете использовать эту способность чтобы убрать n/3 целей из зоны ее поражения. N - ранг персонажа"},{"id":"0x035","name":"Магический мученик","kind":"ability","class_requirement":"Трансгрессор","description":"При получении урона вы можете выпустить вокруг себя волну из вашего запаса кроноса чтобы нанести читсый урон в радиусе 3 ОП. Максимальное значение равно полученному урону"},{"id":"0x036","name":"Умри, но не сейчас","kind":"ability","class_requirement":"Медикус","description":"Если ваш класс - Медикус, а Сущность - Хроно, выберите цель на поле боя, которая получила урон в этом раунде. Отмените этот урон. Цель получит весь этот урон в виде непредотвратимого чистого урона на свой следующий ход. Активное. Раз в бой."},{"id":"0x037","name":"Тик-Так Тактик","kind":"ability","class_requirement":"Медикус","description":"Если ваш класс - Медикус, а Сущность - Хроно, в начале боя вы можете выбрать две цели и поменять их очередь в инициативе местами. Активное"},{"id":"0x038","name":"Мастер Столбов","kind":"ability","class_requirement":"Медикус","description":"Если ваш класс - Медикус, то вы можете использовать базисы Столбов несколько раз. Столбы можно дублировать, при этом КД наступит после конца хода. Каждый ранг выше 5 добавляет 1 столб. На 5 ранге вы можете поставить до 3-хх столбов в 1 раунд (ход). Пассивное."},{"id":"0x039","name":"Ой, а кто это сделал?","kind":"ability","class_requirement":"Медикус","description":"Если ваш класс Медикус Сущности Хроно, то вы можете использовать эту способность для получения эха произошедшего рядом (в пределах средней дистанции) с вашим текущим расположением. На 5 игровых минут вы получаете преимущество на все проверки связанные с тем, что происходило здесь ранее (примеры - поиск ловушек, криминалистика, саперное дело)."},{"id":"0x03a","name":"Я этого не говорил","kind":"ability","class_requirement":"Нейромант","description":"Если ваш класс Нейромант Сущности Пси или Медикус Сущности Хроно, один раз в игровой день вы можете забрать свои слова обратно. Проваленная разговорная проверка может быть прокинута еще раз, со штрафом -15, без преимуществ. Вы обязаны взять полученный результат. Методы разные - суть одна."},{"id":"0x03b","name":"Как мухи на варенье...","kind":"ability","class_requirement":"Нейромант","description":"Если ваш класс - Нейромант, то раз в раунд, вы можете бросить 1 испытание харизмы в базисе факультета Нейромантия с преимуществом. Пассивное."},{"id":"0x03c","name":"Ментальное противостояние","kind":"ability","class_requirement":"Нейромант","description":"Если ваш класс - Нейромант, то в случае, когда вам нужно пройти испытания базиса факультета Нейромантии в качестве цели, вы можете заменить проверяемую характеристику на Харизму. Пассивное."},{"id":"0x03d","name":"Кошмар наяву","kind":"ability","class_requirement":"Нейромант","description":"Если ваш класс - Нейромант. Противники, находящиеся под наложенным вами эффектом «Страх» или «Сон», получают 5n Психического урона в начале своего хода (где n - ваш ранг). Пассивное."},{"id":"0x03e","name":"Ментальная пиявка","kind":"ability","class_requirement":"Нейромант","description":"Если ваш класс - Нейромант. При успешном наложении негативного ментального эффекта на противника, вы восстанавливаете запас ОЗ в размере 20. Пассивное."},{"id":"0x03f","name":"Вторжение в разум","kind":"ability","class_requirement":"Нейромант","description":"Если ваш класс - Нейромант. Выберите цель. Ее следующее испытание против ваших способностей или базисов Нейромантии в этом раунде проходит с помехой. Активное. КД 3."},{"id":"0x040","name":"Коллективное бессознательное","kind":"ability","class_requirement":"Нейромант","description":"Если ваш класс - Нейромант. Раз в бой, при успешном наложении эффекта контроля (Сон, Страх, Дезориентация) на противника, вы можете распространить этот же базис на еще одну цель (она так же проходит испытание базиса) в пределах 2 ОП от первой."},{"id":"0x041","name":"Бэкдор","kind":"ability","class_requirement":"Гейтбрейкер","description":"Вы находите уязвимость в коде, проскальзывая сквозь барьеры словно цифровой призрак. Пройдя испытание Интеллекта против сложности системы, вы можете временно отключить или подчинить себе одного демона Архитектуры/механизм в локальной сети на 1d4 раунда, получая доступ к его функциям."},{"id":"0x042","name":"Тихий взлом","kind":"ability","class_requirement":"Гейтбрейкер","description":"Ваш код звучит как цифровой шепот, мягко переписывая протоколы безопасности. Ваши действия в Архитектуре/локальной сети не повышают уровень тревоги. Вы получаете преимущество на проверки скрытности в сети. При обнаружении у вас есть 1 гарантированный раунд до активации защитных подпрограмм."},{"id":"0x043","name":"Перегрузка ядра","kind":"ability","class_requirement":"Гейтбрейкер","description":"Вы посылаете разрушительный импульс сырого кода, заставляя системы врага захлебываться в бесконечном цикле ошибок. В бою вы заставляете демона/Конструкт пройти спасбросок (Навык первичный взлом против техники). При провале цель получает 'Оцепенение' на 1d3 раунда, теряя возможность действовать."},{"id":"0x044","name":"Многопоточность","kind":"ability","class_requirement":"Гейтбрейкер","description":"Вы можете поддерживать два активных скрипта одновременно. Пассивное."},{"id":"0x045","name":"Дух машины","kind":"ability","class_requirement":"Кочевник","description":"Когда ваш собранный транспорт оказывается на грани уничтожения вы совершаете испытание техники со сложностью 15* количество установленных модулей. При успехе ваш транспорт остается цел с 1 хп, повторное примение способности возможно при ремонте до половины от максимума здоровья"},{"id":"0x046","name":"Школа экстримального вождения","kind":"ability","class_requirement":"Кочевник","description":"Вытягивая все соки из вашей машины вы можете двигаться с большой скоростью с куда меньшим риском чем обычные люди. Вы получаете преймущество на броски техники связанные с вождением. Акт"},{"id":"0x047","name":"Борт-механик","kind":"ability","class_requirement":"Кочевник","description":"Тщательно налаженные процессы под капотом приводят к идеальной эффективности. Вы можете активировать любую систему еще один раз вне зависимости от ее КД"},{"id":"0x048","name":"Полевой врач","kind":"ability","class_requirement":"Мед-Семблер","description":"Треб. класс Мед-Семблер. Вы можете использовать предмет \"Мед. комплект\" на цель на дистанции «Вплотную» в качестве быстрого действия (не тратя Основное Действие)."},{"id":"0x049","name":"Никто не умрет в мою смену","kind":"ability","class_requirement":"Мед-Семблер","description":"Треб. класс Мед-Семблер. Если союзник в предыдущем раунде получил третий провал броска предсмертного состояния и умер, вы все еще можете вытащить его с того света. Находясь на дистанции «Вплотную», потратив 1 раунд, совершите бросок навыка «Хирургия». При результате выше 100, персонаж оживает и выводится из предсмертного состояния с 1 ХП.  На лечение у вас есть один раунд. КД Раз в сутки"},{"id":"0x04a","name":"Комплексная терапия","kind":"ability","class_requirement":"Мед-Семблер","description":"Если ваш класс - Мед-Семблер. При успешном выведении из предсмертного состояния или лечении союзника, вы автоматически снимаете с него один любой числовой негативный эффект без дополнительных затрат. Пассивное."},{"id":"0x04b","name":"Лечебная атмосфера","kind":"ability","class_requirement":"Мед-Семблер","description":"Вместо обычной инъекции препарата вы можете создать быстродействующий аэрозоль, применяя эффект на всех в радиусе 3 ОП от вас"},{"id":"0x04c","name":"Генно-модифицированные жабры","kind":"mutation","class_requirement":null,"description":"Искусственно выращенные жабры. Дают  возможность дышать под водой."},{"id":"0x04d","name":"Фасеточные глаза","kind":"mutation","class_requirement":null,"description":"Глаза с множеством линз. Дают возможность видеть в темноте."},{"id":"0x04e","name":"Симбиотическая кровеносная система","kind":"mutation","class_requirement":null,"description":"Кровь, насыщенная наноботами. Пассивно восстанавливает 10 ОЗ каждый ход в бою не работает в не боя."},{"id":"0x04f","name":"Когти","kind":"mutation","class_requirement":null,"description":"Выдвижные когти не считаются оружием. В бою без оружия дают +40 АТК кровотечение 20"},{"id":"0x050","name":"Биолюминесцентные татуировки","kind":"mutation","class_requirement":null,"description":"Естественные узоры на коже, излучающие мягкое свечение в темноте. Красивая особенность, привлекающая внимание. Бонус к броскам не боевой харизмы +25"},{"id":"0x051","name":"Тепловизионное зрение","kind":"mutation","class_requirement":null,"description":"Способность видеть в инфракрасном спектре. Дает преймущество на обнаружение стелса. Не стакается с фасеточными глазами"},{"id":"0x052","name":"Псио-барьер ума","kind":"mutation","class_requirement":null,"description":"Естественный блок нейронных связей. Дает преимущество на броски Воли против эффектов Страх, Сон и Подавлен."},{"id":"0x053","name":"Гравитационные узлы","kind":"mutation","class_requirement":null,"description":"Особые уплотнения в костях. Уменьшают урон от падения с высоты в 2 раза."},{"id":"0x054","name":"Кроно-регенератор клеток","kind":"mutation","class_requirement":null,"description":"Ускоренный клеточный метаболизм. Выход из предсмертного состояния требует 4 успехов вместо 5."},{"id":"0x055","name":"Ядовитые клыки","kind":"mutation","class_requirement":null,"description":"Железы в зубах, вырабатывающие яд. Дает вам использовать ближнюю атаку с бонусами 4nАТК; 3n ТЧН; 2n КШ;\nИспытание: Телосложение 90\nЭффекты: Отравление 1.\n\nДва раза за бой\n\nn - ранг персонажа"},{"id":"0x056","name":"Крылья","kind":"mutation","class_requirement":null,"description":"Позволяют перемещаться по воздуху. Дает эффект Полет 3"},{"id":"0x057","name":"Прочная чешуя","kind":"mutation","class_requirement":null,"description":"Естественная броня из плотных чешуек. Дает +15 ДЕФ(п.) от термического урона."},{"id":"0x058","name":"Цепкий хвост","kind":"mutation","class_requirement":null,"description":"Позволяет использовать хвост для удержания равновесия или мелких предметов. Дает преимущество на небоевые броски Ловкости."},{"id":"0x059","name":"Кроно-резонаторные кристаллиты","kind":"mutation","class_requirement":null,"description":"Мелкие вкрапления кристаллов в коже. Позволяют раз в день восстановить 20*n Кроноса вне жилья. (где n - ранг вашего персонажа)"},{"id":"0x05a","name":"Рога","kind":"mutation","class_requirement":null,"description":"Крепкие рога на голове. Позволяют совершать ближнюю атаку. Цель проходит испытание Силы (90), при провале получает эффект Дезориентация 1 и кровоток 20."},{"id":"0x05b","name":"Термическая стойкость","kind":"mutation","class_requirement":null,"description":"Ваше тело приспособлено к холоду. Дает +15 деф(п) при уроне Крио"},{"id":"0x05c","name":"Неутомимость","kind":"mutation","class_requirement":null,"description":"Для вас усталость наступает на 3 раунда позже"},{"id":"0x05d","name":"Саморегулирующаяся кровеносная система","kind":"mutation","class_requirement":null,"description":"Урон от кровотечения снижается на 20"},{"id":"0x05e","name":"Истинная всеядность","kind":"mutation","class_requirement":null,"description":"Вы устойчивы к пищевым и химическим отравлениям, эффект ОТРАВЛЕН действует на вас в два раза слабее"},{"id":"0x05f","name":"Ментальные блокаторы","kind":"mutation","class_requirement":null,"description":"Ваше сознание сопротивляется воздействию извне, проверки испытаний против карт нейроманта получают бонус + 15"},{"id":"0x060","name":"Несломленный","kind":"mutation","class_requirement":null,"description":"Ваш разум непоколебим, действия под действием эффекта страха получают бонус +20"},{"id":"0x061","name":"Выживший","kind":"mutation","class_requirement":null,"description":"Даже на грани смерти вы сражаетесь. Пока ваше ОЗ ниже 10% вы получаете преймущество на боевые броски"},{"id":"0x062","name":"Термостабильная кожа","kind":"mutation","class_requirement":null,"description":"Вы устойчивы к морозам благодоря особой коже которая слабо проводит тепловую энергию, в результате  чтобы заметить вас  с помощью тепловизора необходимо прокинуть дополнительное испытание восприятия 60"}]$j$::jsonb);
insert into beasts ("id", "group_name", "name", "description") select "id", "group_name", "name", "description" from jsonb_populate_recordset(null::beasts, $j$[{"id":"0x001","group_name":"Хищник","name":"Путь городского хищника","description":"Общение с людьми дается вас особенно легко, тот кто слышат ваш голос должен пройти проверку воли 10n, при провале цель лучше к вам относиться (считается обвороженной) и ощущают доверие по отношению к вам. Первый раунд боя будет считаться для цели неожиданным. КЦ 1 + n/4\n\nn - количество способностей зверя\n\nТрата ХП 20\n\nТРЕБ: класс - зверь, отсутствие других способностей путей. Только вне активного боя."},{"id":"0x002","group_name":"Хищник","name":"Обворожительное присутствие","description":"Окружающие чувствуют себя уверенно рядом с вами, и выражают желание выделиться и не упасть в грязь лицом. Союзники при вашем прямом присутствии получают бонус 2n на все боевые и не боевые броски, пока ваше здоровье больше половины, слуги получают бонус 5n\n\n(n равно количеству взятых способностей зверя)\n\nТРЕБ: Класс - Зверь; Способность - Путь городского хищника\n\nПассивная.\n\nПри наличии двух зверей с этой способностью применяется та что приносит самый большой эффект"},{"id":"0x003","group_name":"Хищник","name":"Затягивание ошейника","description":"Те кем вы питаетесь становятся вашими слугами и обязаны выполнять все ваши приказы, чтобы пойти на перекор слуга должен пройти испытание воли равное 10n\n(n количество взятых способностей зверя)\n\nТРЕБ:Класс - Зверь; Способность - Путь городского хищника\n\nПассивная"},{"id":"0x004","group_name":"Хищник","name":"Просьба","description":"Цель должна победить в соревновании «Воли против Харизмы» со штрафом –5n. В противном случае цель должна выполнить ваш прямой запрос (не длиннее трех слов). Запрос не должен вредить цели и тем, кого она считает союзниками, просьба не может накладывать эффекты и действует в течении 1 АКТ. В противном случае просьба считается неуспешной, а очарование спадает.\n\nn - количество способностей зверя\n\nприм:-Можешь открыть дверь?;Подай мне ключи; Выйди из комнаты\n\nТрата ХП 40\n\nТреб: Класс - Зверь, Способность - Обворожительное присутствие"},{"id":"0x005","group_name":"Хищник","name":"Приказ","description":"Любая цель должна преуспеть в соревновании Воли против вашей Харизмы с бонусом +15. Вы получаете бонус 5 за каждую взятую способность зверя. При провале цель должна выполнить ваш приказ, который можно выполнить, потратив 1 ОД. Если приказ навредит здоровью цели или её союзников, бонус к броску Воли увеличивается до +30.\n\nТрата хп 60\n\nТреб: Класс - Зверь, Способность - Просьба"},{"id":"0x006","group_name":"Хищник","name":"Сила в стае","description":"Находясь в окружении разумных союзников, вы чувствуете прилив сил, получая бонус к боевым броскам +n, а к деф п +n*2 за каждого союзника. Если союзник является слугой, бонус удваивается.n - количество взятых способностей зверя. Союзниками в бою могут считаться только те кто напрямую принимаем участице в сцене на вашей стороне\n\nТреб: Класс - Зверь, Способность - Просьба"},{"id":"0x007","group_name":"Хищник","name":"Приготовление","description":"Обвороженная вами цель не сопротивляется в первом раунде вашего питания\n\nТреб: Класс - Зверь, Способность - Сила в стае"},{"id":"0x008","group_name":"Хищник","name":"Убеждение защиты","description":"Выйдя вперед, вы можете силой воли заставить противника на расстоянии до 6 ОП замереть на протяжении раунда и не предпринимать каких либо действий при провале испытания Воли (8n).Испытания ввыполняются как обычно. n - количество способностей зверя\n\nТрата ХП: 100\n\nКД: 2\n\nТреб: Класс - Зверь, Способность - Сила в стае"},{"id":"0x009","group_name":"Сокрытие","name":"Путь сокрытия","description":"Вы обретаете частичную власть над тенью. Плотный слой тьмы окутывает ваши движения, скрывая присутствие подобно эффекту невидимости. Эффект рассеивается, если вы совершаете неаккуратное действие или попадаете под прямой свет. Сложность обнаружения цели равна результату броска навыка «Скрытность».Так же вы получаете возможность видеть в темноте, не получая за нее никаких штрафов.\n\nВаш метод питания отличается - вы **можете** совершать действие питания используя бросок атаки сокрытым оружием на расстоянии если цель находиться в темноте, на дистанции до 5 ОП от вас\n\nТрата хп 50\n\nТреб: Класс Зверь, отсутствие способности путей"},{"id":"0x00a","group_name":"Сокрытие","name":"Теневое отражение","description":"Вы можете размыть свой силуэт, создавая 3 похожие копии себя в непосредственной близости и усложняя атаки по вам. При атаке по вам киньте кубик d6: если результат больше, чем 6 – n, атака уходит в копию, и та пропадает. n — количество копий. Защита не влияет на уничтожение копии.\n\nТрата ХП 50\n\nТреб: Класс - Зверь, Способность - Путь Сокрытия"},{"id":"0x00b","group_name":"Сокрытие","name":"Расширение домена","description":"Вы можете сокрыть тенью дополнительные цели помимо себя. Количество целей равно n/3 (с округлением вниз), где n — количество способостей зверя.\n\nЕсли один из членов группы снимает покров, эффект пропадает у всех одновременно.\n\nТреб: Класс - Зверь, Способность - Теневое отражение"},{"id":"0x00c","group_name":"Сокрытие","name":"Истинное скрытое ношение","description":"Оружие которое вы держите в руках становиться невидимым для большинства окружающих а атаки с такого оружия не снимают невидимость. Только одно оружие может быть скрыто одновременно. Невидимость оружия спадает при обнаружении. Сложность обнаружения =навык скрытного ношения и не ограничивается типом оружия\n\nТрата ХП 20\n\nТреб: Класс - Зверь, Способность - Теневое отражение"},{"id":"0x00d","group_name":"Сокрытие","name":"Раскрытие потенциала оружия","description":"Атаки нанесенные из сокрытого оружия получают +8n АТК; +3n ТЧН; +2 КШ; где n количество взятых способностей зверя.Пассивная\n\nТреб: Класс - Зверь, Способность - Истинное скрытое ношение"},{"id":"0x00e","group_name":"Сокрытие","name":"Единение с тенью","description":"Находясь в состоянии скрытности благодаря вашей способности и находясь в неосвещённом месте, вы восстанавливаете по 20 ХП в раунд. Вы можете увеличить получаемое лечение, тратя ваши доступные ОД, 20 хп за одно очко действия\n\nТреб: Класс - Зверь, Способность - Истинное скрытое ношение"},{"id":"0x00f","group_name":"Сокрытие","name":"Контроль територрии","description":"Вы постигаете более широкий контроль над тенями, что позволяет вам покрыть непроглядной тьмой участок диаметром 5 оп на протяжении 5 АКТ. Любые источники света в этой зоне перестают его излучать. Первые действия в раунде  тех, кто сокрыт вашими тенями, включая вас, получают преимущество.\n\nТрата ХП 100\n\nТреб: Класс - зверь; Способность - расширение домена;"},{"id":"0x010","group_name":"Сокрытие","name":"Аватар тени","description":"Вы можете призвать материальную копию себя, сотканную из теней. Копия обладает всеми вашими показателями, способностями, снаряжением и навыками, за исключением питания и расходников, а также неспособна восстанавливать здоровье. Копия легко отличима и не похожа на обычного человека\n\nТрата ХП 50 каждый ход поддержания копии\n\nДействует в течении 15 минут или до конца боя, что будет дольше. В конце боя пропадает. Максимум 1 копия\n\nТреб: Класс - Зверь, Способность - Единение с тенью"},{"id":"0x011","group_name":"Сокрытие","name":"Званный ужин","description":"Ваша теневая копия получает возможность питаться, но вместо восстановления собственного здоровья она восстанавливает ваше, наносимый таким образом урон уменьшается в два раза, а сама копия не может использовать способности: Голод подождет, голод превыше всего. Если ваша копия уничтожается во время питания вы получаете эффект оцепенение АКТ 2\n\nТреб:Класс - Зверь, Способность - Аватар тени"},{"id":"0x012","group_name":"Изменение","name":"Путь изменений","description":"Вы можете изменить свое физическое тело: рост, вес, внешность и даже пол. Вы всё ещё остаётесь гуманоидом в пределах своего исходного размера. Сложность восприятия при попытке вас обнаружить после этой процедуры равна результату броска навыка «Маскировка».\n\nТрата ХП 30\n\nТреб: Класс - Зверь. Отсутствие других способностей путей"},{"id":"0x013","group_name":"Изменение","name":"Практичное искусство","description":"Изменение облика позволяет отрастить ближнее оружие, созданное из вашей плоти и кости. На создание оружия вы тратите очки изменения равные количеству ваших способностей зверя.\n\nАТК +15 - 1 очко (не больше n*8)\n\nКШ +5 - 1 очко (не больше n*4)\n\nТЧН +5 -1 очко (не больше n*4)\n\nДЕФ(п) +4 -1 очко (не больше n*3)\n\nДеф(а) +5 - 1 очко (не больше n*2) -вложение одного очка делает оружие щитом\n\nДоп АВХ -2 очка (не больше n/3 округление вниз)\n\nДополнительные свойства\n\nДоп дальность +1 - 2 очка\n\nКровотечение 10 - 1 очко\n\nДезориентация/перелом ВЕР 4n - 2 очка (на выбор, берется один раз)\n\nТочное - 2 очка\n\nНелетальное - 1 очко\n\nСчитается как безоружный бой / тяжелое - 3 очка\n\nn - количество полученных способностей зверя\n\nТреб: Класс - Зверь, Способность - Путь изменений"},{"id":"0x014","group_name":"Изменение","name":"Репетиция облика","description":"Цель, которая не сопротивляется или находится в недееспособном состоянии, меняет облик по желанию зверя: вес, рост, внешний вид и пол, оставаясь в пределах оригинального размера. Сложность восприятия после процедуры равна броску Прикладного искусства.\n\nТрата ХП цели 30 \n\nТреб: Класс - Зверь, Способность - Путь изменений"},{"id":"0x015","group_name":"Изменение","name":"Приманка","description":"Ваш изменённый облик становится очень привлекательным для окружающих. Броски Харизмы получают бонус +5n, где n - количество взятых способностей зверя.\n\nТреб: Класс - Зверь, Способность - Развитие тела"},{"id":"0x016","group_name":"Изменение","name":"Развитие тела","description":"Навыки, Ловкости и Силы, которые вами изучены, получают бонус +5n к броскам, пока вы находитесь в изменённой форме. n равно количеству взятых способностей зверя. \n\nТрата ХП 60 \n\nТреб: Класс - Зверь, Способность - Практичное исскуство"},{"id":"0x017","group_name":"Изменение","name":"Кровавый цветок","description":"Вы мгновенно наращиваете множество шипов на своем теле, все цели находящиеся в радиусе 1 ОП от вас получают атаку от телосложения с бонусом 15n атк 5n КШ. Где n - количество способностей зверяКД 1\n\nТрата ХП 70\n\nТреб: Класс - Зверь, Способность - Схлопывание ловушки"},{"id":"0x018","group_name":"Изменение","name":"Схлопывание ловушки","description":"Питание при измененном облике становиться проще, ваша цель получает помеху к высвобождению во время процесса.\n\nТреб: Класс - Зверь, Способность - Приманка\n\nПассивная"},{"id":"0x019","group_name":"Изменение","name":"Апекс развития","description":"Изменяя форму, вы можете стать на один размер больше оригинального, получая дополнительные преимущества и развивая границы своего тела:\n\nДоп. ХП: +100\n\nДоп АТК +20\n\nДеф(П): +60\n\nДоп. ОД (до конца боя): +1\n\nДеф(А): +30\n\nУклонение: +70\n\nТрата ХП: 50 за каждый ход поддержания формы\n\nПосле конца боя форма спадает и не может быть использована в течение 4 часов.\n\nТреб: Класс - Зверь, Способность - Схлопывание ловушки"},{"id":"0x01a","group_name":"Общие","name":"Кровавая ярость","description":"Приближая свою душу к забвению (находясь ниже половины своего максимального ХП), вы подключаете скрытые резервы организма, получая дополнительный АВХ на все ваши атаки и дополнительные 2 ОП до тех пор, пока ваше ХП не станет больше половины.\n\nТреб: Класс - Зверь\n\nПассивная"},{"id":"0x01b","group_name":"Общие","name":"Отчаяние","description":"Находясь в состоянии кровавой ярости, если вы наносите урон цели после совершения атаки в ближнем бою, вы можете отказаться от всех своих других действий и восстановить 80 ХП за изначальную атаку и 40 ХП за каждое потраченное на это ОД\n\nКД 2\n\nТреб: Класс - Зверь, Способность - Кровавая ярость"},{"id":"0x01c","group_name":"Общие","name":"Здоровое питание","description":"Питание слабыми личностями (не игровыми персонажами) даже после смерти позволяет восстановить ваше здоровье до максимума,если ваше здоровье уже на максимуме вы можете получить до 20n доп хп. Где n - количество способностей зверя. Максимум доп хп от этой способности ограничивается 20n  Где n - количество способностей зверя.\n\nтолько вне боя"},{"id":"0x01d","group_name":"Общие","name":"Голод превыше всего","description":"Вы можете питаться во время боя, ускоряя процесс на раунд, не может уменьшить количество необходимых раундов меньше одного. Несовместимо с \"Голод подождет\"\n\nТреб: Класс - Зверь"},{"id":"0x01e","group_name":"Общие","name":"Голод подождет","description":"Вы можете питаться во время боя, оставляя возможность выполнять защитные действия. Несовместимо с \"Голод превыше всего\"\n\nТреб: Класс - Зверь\n\nПассивная"},{"id":"0x01f","group_name":"Общие","name":"Очистка тела","description":"Вы снимаете с себя качественно n/3 эффектов с округлением вниз, не меньше одного, где n количество взятых способностей зверя. КД 2\n\nТрата ХП 35\n\nТреб: Класс - Зверь"},{"id":"0x020","group_name":"Общие","name":"Стремительность","description":"Вы получаете 1 доп ОД и доп ОП в количестве n/2+1 с округлением вниз, где n количество взятых способностей зверя КД 2\n\nТрата ХП 50\n\nТреб: Класс - Зверь"}]$j$::jsonb);
insert into traits ("id", "name", "description") select "id", "name", "description" from jsonb_populate_recordset(null::traits, $j$[{"id":"0x001","name":"Пилот","description":"Пилотирование: +15 При пятом уровне прокачки к броску навыка. \nВождение (гражданский транспорт): +15 При пятом уровне прокачки к броску навыка. \nКапитан: При пятом уровне прокачки +15 к броску навыка.  \n\nЕсли какого то из навыков у персонажа нет он кидает его без помехи."},{"id":"0x002","name":"Атлет","description":"Атлетика: +15 При пятом уровне прокачки к броску навыка\nПлавание: +15 При пятом уровне прокачки к броску навыка\nНеутомимость: уменьшает эффект усталости на 5 за уровень эффекта\n\nЕсли какого то из навыков у персонажа нет он кидает его без помехи."},{"id":"0x003","name":"Боевой медик","description":"Первая помощь: +15 При пятом уровне прокачки к броску навыка\nХирургия: +15 При пятом уровне прокачки к броску навыка\nМилосердность: +15 При пятом уровне прокачки к броску навыка\n\nЕсли какого то из навыков у персонажа нет он кидает его без помехи."},{"id":"0x004","name":"Биотехник","description":"Знание имплантов: Позволяет распознавать импланты на 1 уровень редкости выше\nУстановка имплантов: +15 При пятом уровне прокачки к броску навыка\nБиоинжинерия: +15 При пятом уровне прокачки к броску навыка\n\nЕсли какого то из навыков у персонажа нет он кидает его без помехи."},{"id":"0x005","name":"Охотник за головами","description":"Слежка: +15 При пятом уровне прокачки к броску навыка\nОхотник: +15 При пятом уровне прокачки к броску навыка\nОхотник на убийц: +15 При пятом уровне прокачки к броску навыка\n\nЕсли какого то из навыков у персонажа нет он кидает его без помехи."},{"id":"0x006","name":"Бюрократ","description":"Поиск информации в омнинете: +15 При пятом уровне прокачки к броску навыка\nОбщая эрудиция: +15 При пятом уровне прокачки к броску навыка\nКриптография: +15 При пятом уровне прокачки к броску навыка\n\nЕсли какого то из навыков у персонажа нет он кидает его без помехи."},{"id":"0x007","name":"Военный","description":"Устрашение: +15 При пятом уровне прокачки к броску навыка\nMaстер тактик: Увеличивает КЦ (количество союзников) на 1\nБоевой гимн: Увеличивает бафф эффекта дополнительно на +10\n\nЕсли какого то из навыков у персонажа нет он кидает его без помехи."},{"id":"0x008","name":"Корпоративный агент","description":"Этикет: +15 При пятом уровне прокачки к броску навыка\nМастер лжи и обмана: +15 При пятом уровне прокачки к броску навыка\nОценка: +15 При пятом уровне прокачки к броску навыка\n\nЕсли какого то из навыков у персонажа нет он кидает его без помехи."},{"id":"0x009","name":"Культист","description":"Знание рун: +15 При пятом уровне прокачки к броску навыка\nЗнание кронологии: +15 При пятом уровне прокачки к броску навыка\nУбеждение: +15 При пятом уровне прокачки к броску навыка\n\nЕсли какого то из навыков у персонажа нет он кидает его без помехи."},{"id":"0x00a","name":"Дипломат","description":"Дипломатия: +15 При пятом уровне прокачки к броску навыка\nУбеждение: +15 При пятом уровне прокачки к броску навыка\nОчарование: +15 При пятом уровне прокачки к броску навыка \n\nЕсли какого то из навыков у персонажа нет он кидает его без помехи."},{"id":"0x00b","name":"Член банды","description":"Запугивание/Устрашение: +15 При пятом уровне прокачки к броску навыка\nДорога ярости: +15 При пятом уровне прокачки к броску навыка\nСкрытое ношение: +15 При пятом уровне прокачки к броску навыка\n\nЕсли какого то из навыков у персонажа нет он кидает его без помехи."},{"id":"0x00c","name":"Роботехник","description":"Высокотехнологичный ремонт: +15 При пятом уровне прокачки к броску навыка\nУстановка улучшений: +15 При пятом уровне прокачки к броску навыка\nЗнание электроники: +15 При пятом уровне прокачки к броску навыка\n\nЕсли какого то из навыков у персонажа нет он кидает его без помехи."},{"id":"0x00d","name":"Исследователь","description":"Картография: +15 При пятом уровне прокачки к броску навыка\nВнимательность: +15 При пятом у